# Major market indices — displayed at the top of the sector page
MAJOR_INDICES: list[tuple[str, str]] = [
    ("000001", "上证指数"),
    ("399001", "深证成指"),
    ("899050", "北交所指数"),
    ("HSI",    "恒生指数"),
]


def get_all_sectors() -> list[dict]:
    """Return all sectors with their representative stocks."""
    return [
        {
            "name": sector,
            "stocks": [
                {"ticker": s.ticker, "name": s.name, "desc": s.desc}
                for s in stocks
            ],
        }
        for sector, stocks in SECTOR_STOCKS.items()
    ]


def get_sectors_with_market_data() -> list[dict]:
    """Return all sectors enriched with live quotes and rankings.

    For each sector, batch-fetches current quotes for the representative
    stocks, then produces three rankings:
      - top_gainers:  sorted by change_pct desc  (今日涨幅)
      - top_turnover: sorted by turnover desc     (资金活跃)
      - top_volume:   sorted by volume desc        (成交量)
    """
    # Collect all unique tickers across sectors
    all_tickers: list[str] = []
    for stocks in SECTOR_STOCKS.values():
        for s in stocks:
            raw = s.ticker.split(".")[0]
            if raw not in all_tickers:
                all_tickers.append(raw)

    # Batch fetch all quotes in one call — any network failure falls back to empty
    try:
        quotes = get_batch_quotes_tencent(all_tickers)
    except Exception:  # noqa: BLE001
        quotes = []
    quote_map: dict[str, dict] = {}
    for q in quotes:
        # Map by raw 6-digit code for easy lookup
        raw = q.ticker.split(".")[0]
        quote_map[raw] = {
            "ticker": q.ticker,
            "name": q.name,
            "price": q.price,
            "change": round(q.change, 2),
            "change_pct": round(q.change_pct, 2),
            "turnover": q.turnover,
            "volume": q.volume,
        }

    result: list[dict] = []
    for sector_name, stocks in SECTOR_STOCKS.items():
        # Build stock list with live data
        stock_data: list[dict] = []
        for s in stocks:
            raw = s.ticker.split(".")[0]
            live = quote_map.get(raw)
            entry = {
                "ticker": s.ticker,
                "name": s.name,
                "desc": s.desc,
                "price": live["price"] if live else None,
                "change": live["change"] if live else None,
                "change_pct": live["change_pct"] if live else None,
                "turnover": live["turnover"] if live else None,
                "volume": live["volume"] if live else None,
            }
            stock_data.append(entry)

        # Rankings (only stocks with valid data)
        valid = [s for s in stock_data if s["price"] is not None]

        top_gainers = sorted(
            valid, key=lambda x: x["change_pct"] or 0, reverse=True
        )[:5]
        top_turnover = sorted(
            valid, key=lambda x: x["turnover"] or 0, reverse=True
        )[:5]
        top_volume = sorted(
            valid, key=lambda x: x["volume"] or 0, reverse=True
        )[:5]

        result.append({
            "name": sector_name,
            "stocks": stock_data,
            "top_gainers": top_gainers,
            "top_turnover": top_turnover,
            "top_volume": top_volume,
        })

    return result


def get_major_indices() -> list[dict]:
    """Fetch live quotes for major market indices.

    Uses Tencent qt.gtimg.cn with special index symbol prefixes:
      - sh000001 = 上证指数
      - sz399001 = 深证成指
      - bj899050 = 北交所指数 (fallback: sz899050)
      - hkHSI    = 恒生指数
    """
    # Map (code, name) → Tencent symbol
    symbol_map: dict[str, str] = {
        "000001": "sh000001",
        "399001": "sz399001",
        "899050": "bj899050",
        "HSI": "hkHSI",
    }

    symbols = list(symbol_map.values())
    url = "http://qt.gtimg.cn/q=" + ",".join(symbols)

    results: list[dict] = []
    try:
        req = Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urlopen(req, timeout=8) as resp:  # nosec B310
            text = resp.read().decode("gbk", errors="ignore")
    except Exception:  # noqa: BLE001 — catch IncompleteRead, URLError, etc.
        return results

    # Parse each line: v_sh000001="1~上证指数~000001~3352.00~..."
    for code, label in MAJOR_INDICES:
        sym = symbol_map.get(code, "")
        # Find the line for this symbol
        marker = f"v_{sym}=\""
        idx = text.find(marker)
        if idx < 0:
            # Try fallback for 北交所: sz prefix
            if code == "899050":
                marker = 'v_sz899050="'
                idx = text.find(marker)
            if idx < 0:
                results.append({"code": code, "name": label, "price": None,
                                "change": None, "change_pct": None})
                continue

        start = idx + len(marker)
        end = text.find('"', start)
        payload = text[start:end] if end > start else ""
        fields = payload.split("~")

        if len(fields) < 5:
            results.append({"code": code, "name": label, "price": None,
                            "change": None, "change_pct": None})
            continue

        try:
            price = float(fields[3])
            prev = float(fields[4])
            change = price - prev
            change_pct = (change / prev * 100) if prev else 0.0
        except (ValueError, IndexError):
            results.append({"code": code, "name": label, "price": None,
                            "change": None, "change_pct": None})
            continue

        results.append({
            "code": code,
            "name": fields[1] or label,
            "price": round(price, 2),
            "change": round(change, 2),
            "change_pct": round(change_pct, 2),
        })

    return results
